<template>
  <div class="space-y-5">
    <PageHeader title="插件详情" description="查看版本、权限与兼容性后再安装" :breadcrumbs="[{ label: '插件市场', to: '/app/plugin-market' }, { label: item?.name || '插件详情' }]">
      <template #actions><router-link class="secondary-button" to="/app/plugin-market"><i class="fa fa-arrow-left"></i> 返回市场</router-link></template>
    </PageHeader>
    <PageState v-if="loading || error || !item" :type="loading ? 'loading' : error ? 'error' : 'empty'" :icon="loading ? 'fa fa-spinner fa-spin' : 'fa fa-puzzle-piece'" :title="loading ? '正在加载插件详情' : error || '插件不存在'" :description="error || '该插件可能已下架或当前账号无权访问'" :action-text="error ? '重试' : ''" @action="load" />
    <template v-else>
      <section class="detail-hero">
        <div class="detail-icon" :class="item.pluginType === 'LOCAL_PLUGIN' ? 'is-local' : ''"><i :class="item.pluginType === 'LOCAL_PLUGIN' ? 'fa fa-desktop' : 'fa fa-cloud'"></i></div>
        <div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><h2 class="text-2xl font-bold text-neutral-900">{{ item.name }}</h2><span class="badge">v{{ item.latestVersion }}</span></div><p class="mt-1 font-mono text-xs text-neutral-400">{{ item.slug }} · {{ item.authorDisplayName }}</p><p class="mt-4 max-w-2xl text-sm leading-6 text-neutral-600">{{ item.description || '暂无详细描述' }}</p></div>
        <div class="detail-actions"><button class="primary-button" type="button" @click="openInstall"><i class="fa fa-download"></i> 安装</button><span class="rating"><i class="fa fa-star"></i> {{ Number(item.averageRating).toFixed(1) }}（{{ item.ratingCount }}）</span></div>
      </section>
      <div class="detail-grid">
        <main class="space-y-4">
          <section class="detail-card"><h3>能力与兼容性</h3><div class="tag-list"><span v-for="platform in platforms" :key="platform">{{ platform }}</span><span v-for="capability in capabilities" :key="capability">{{ capability }}</span></div><p v-if="!platforms.length && !capabilities.length" class="muted">暂无扩展能力声明</p></section>
          <section class="detail-card"><h3>版本与安全</h3><dl class="meta-grid"><div><dt>发布版本</dt><dd>{{ item.latestVersion }}</dd></div><div><dt>发布时间</dt><dd>{{ formatDate(item.publishedAt) }}</dd></div><div><dt>安装次数</dt><dd>{{ item.installationCount }}</dd></div><div><dt>权限声明</dt><dd>{{ permissions.length }} 项</dd></div></dl><p class="security-note"><i class="fa fa-shield"></i> 安装后仍受空间权限、插件权限声明和隔离运行时的最小交集约束。</p></section>
          <section class="detail-card"><h3>评分与评论</h3><form class="rating-form" @submit.prevent="submitRating"><select v-model.number="rating"><option v-for="value in [5,4,3,2,1]" :key="value" :value="value">{{ value }} 星</option></select><input v-model.trim="comment" maxlength="500" placeholder="分享你的使用体验（可选）" /><button class="secondary-button" type="submit" :disabled="ratingSubmitting">提交</button></form><p class="muted">评论会进入内容审核队列，暂不展示未经审核的原文。</p></section>
        </main>
        <aside class="detail-card permissions-card"><h3>安装权限</h3><ul><li v-for="permission in permissions" :key="permission"><i class="fa fa-check-circle"></i>{{ permissionLabel(permission) }}</li><li v-if="!permissions.length" class="muted">插件未声明额外权限</li></ul><p class="muted">你可以在安装确认弹窗中逐项撤销授权。</p></aside>
      </div>
    </template>
    <div v-if="installing" class="fixed inset-0 z-[110] flex items-center justify-center bg-black/40 p-4" @click.self="installing = false"><section class="install-dialog"><header><h3>安装 {{ item?.name }}</h3><button class="icon-button" type="button" @click="installing = false"><i class="fa fa-times"></i></button></header><p>请选择安装范围并确认权限。空间安装需要当前空间的插件管理权限。</p><div class="permission-list"><label v-for="permission in permissions" :key="permission"><input v-model="grantedPermissions" type="checkbox" :value="permission" />{{ permissionLabel(permission) }}</label></div><div class="dialog-actions"><button class="secondary-button" type="button" :disabled="installingBusy" @click="install(false)">安装到个人</button><button class="primary-button" type="button" :disabled="installingBusy || spaceStore.isPersonalSpace" @click="install(true)">安装到当前空间</button></div><small v-if="spaceStore.isPersonalSpace">请先切换到团队或企业空间。</small></section></div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PageHeader from '@/components/common/PageHeader.vue'
import PageState from '@/components/common/PageState.vue'
import { installPluginForSpaceApi, installPluginForUserApi, listPluginMarketplaceApi, rateMarketplacePluginApi, type MarketplacePlugin } from '@/api/modules/plugins'
import { useSpaceStore } from '@/stores/spaceStore'
import { useToastStore } from '@/stores/toastStore'

const route = useRoute(); const router = useRouter(); const toast = useToastStore(); const spaceStore = useSpaceStore()
const item = ref<MarketplacePlugin | null>(null); const loading = ref(false); const error = ref(''); const installing = ref(false); const installingBusy = ref(false); const grantedPermissions = ref<string[]>([]); const rating = ref(5); const comment = ref(''); const ratingSubmitting = ref(false)
const permissions = computed(() => parseJson(item.value?.permissionConfig)); const platforms = computed(() => parseJson(item.value?.supportedPlatformsJson)); const capabilities = computed(() => parseJson(item.value?.capabilitiesJson))
function parseJson(value?: string): string[] { try { const result = value ? JSON.parse(value) : []; return Array.isArray(result) ? result.filter((entry) => typeof entry === 'string') : [] } catch { return [] } }
async function load() { loading.value = true; error.value = ''; try { const result = await listPluginMarketplaceApi('', ''); item.value = result.data.find((candidate) => candidate.pluginId === String(route.params.pluginId)) || null; if (!item.value) error.value = '插件不存在或已下架' } catch (err: any) { error.value = err?.message || '插件详情加载失败' } finally { loading.value = false } }
function openInstall() { if (!item.value) return; grantedPermissions.value = [...permissions.value]; installing.value = true }
async function install(toSpace: boolean) { if (!item.value || installingBusy.value) return; installingBusy.value = true; try { if (toSpace) await installPluginForSpaceApi(item.value.pluginId, item.value.latestVersion, grantedPermissions.value); else await installPluginForUserApi(item.value.pluginId, item.value.latestVersion, grantedPermissions.value); toast.showToast(toSpace ? '插件已安装到当前空间' : '插件已安装到个人账号', 'success'); installing.value = false; router.push('/app/plugins') } catch (err: any) { toast.showToast(err?.message || '安装失败', 'error') } finally { installingBusy.value = false } }
async function submitRating() { if (!item.value || ratingSubmitting.value) return; ratingSubmitting.value = true; try { await rateMarketplacePluginApi(item.value.pluginId, rating.value, comment.value); toast.showToast('评分已提交，审核通过后展示', 'success'); comment.value = '' } catch (err: any) { toast.showToast(err?.message || '评分提交失败', 'error') } finally { ratingSubmitting.value = false } }
function permissionLabel(value: string) { const labels: Record<string, string> = { 'file.content.read': '读取激活文件内容', 'file.metadata.write': '修改文件元数据', 'file.content.write_pre_activation': '激活前回写文件内容', 'client.file.read': '读取用户选择的本地文件', 'client.file.upload': '上传文件', 'plugin.log.write': '记录脱敏执行日志' }; return labels[value] || value }
function formatDate(value: string) { return value ? new Date(value).toLocaleDateString() : '—' }
onMounted(load)
</script>

<style scoped>
.detail-hero{display:flex;flex-wrap:wrap;gap:18px;align-items:center;border:1px solid #dbe4f0;border-radius:22px;background:linear-gradient(135deg,#eff6ff,#fff 55%,#f5f3ff);padding:24px;}.detail-icon{display:flex;width:68px;height:68px;align-items:center;justify-content:center;border-radius:18px;background:#dbeafe;color:#2563eb;font-size:28px;}.detail-icon.is-local{background:#ede9fe;color:#7c3aed;}.detail-actions{display:flex;align-items:center;gap:12px;flex-direction:column;}.badge,.tag-list span{border-radius:999px;background:#eef2ff;padding:4px 8px;color:#4f46e5;font-size:10px;font-weight:700;}.rating{color:#b45309;font-size:11px;}.detail-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:16px;}.detail-card{border:1px solid #e2e8f0;border-radius:18px;background:#fff;padding:18px;box-shadow:0 5px 18px rgba(15,23,42,.04);}.detail-card h3{margin-bottom:14px;color:#334155;font-size:14px;font-weight:700;}.tag-list{display:flex;flex-wrap:wrap;gap:7px;}.tag-list span{background:#f1f5f9;color:#475569;}.meta-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;}.meta-grid dt{color:#94a3b8;font-size:10px;}.meta-grid dd{margin-top:3px;color:#334155;font-size:13px;font-weight:700;}.security-note{margin-top:16px;border-radius:10px;background:#f0fdf4;padding:10px;color:#15803d;font-size:11px;line-height:1.5;}.permissions-card li{display:flex;align-items:center;gap:8px;padding:7px 0;color:#475569;font-size:12px;}.permissions-card li i{color:#16a34a;}.muted{color:#94a3b8;font-size:11px;line-height:1.6;}.rating-form{display:flex;gap:8px;}.rating-form select,.rating-form input{min-height:36px;border:1px solid #dbe4f0;border-radius:9px;padding:0 9px;color:#475569;font-size:12px;outline:none;}.rating-form input{min-width:0;flex:1;}.primary-button,.secondary-button{display:inline-flex;min-height:38px;align-items:center;gap:7px;border-radius:9px;padding:0 13px;font-size:12px;font-weight:700;}.primary-button{background:#2563eb;color:#fff;}.secondary-button{border:1px solid #dbe4f0;background:#fff;color:#475569;}.install-dialog{width:min(100%,480px);border-radius:18px;background:#fff;padding:20px;box-shadow:0 22px 60px rgba(15,23,42,.24);}.install-dialog header{display:flex;align-items:center;justify-content:space-between;}.install-dialog h3{font-size:16px;font-weight:700;color:#1e293b;}.install-dialog>p{margin-top:8px;color:#64748b;font-size:12px;line-height:1.6;}.permission-list{display:grid;gap:8px;margin-top:14px;}.permission-list label{display:flex;gap:8px;align-items:center;border-radius:9px;background:#f8fafc;padding:9px;color:#475569;font-size:12px;}.dialog-actions{display:flex;gap:8px;margin-top:18px;}.dialog-actions>*{flex:1;justify-content:center;}.install-dialog small{display:block;margin-top:8px;text-align:center;color:#94a3b8;font-size:10px;}@media(max-width:767px){.detail-grid{grid-template-columns:1fr}.detail-actions{width:100%;align-items:stretch;}.detail-actions .primary-button{justify-content:center}.rating-form{flex-wrap:wrap}.rating-form input{width:100%;flex-basis:100%;}.detail-hero{padding:18px;}}
</style>
